let updated = 0;
const missing = [];

const result = seeds.map((seed) => {
  const entry = DESCRIPTIONS[seed.id];
  if (!entry) {
    return seed;
  }
  updated += 1;
  return {
    ...seed,
    description: entry.fr,
    descriptionEn: entry.en,
  };
});

const ids = new Set(seeds.map((seed) => seed.id));
for (const id of Object.keys(DESCRIPTIONS)) {
  if (!ids.has(id)) {
    missing.push(id);
  }
}

fs.writeFileSync(seedsPath, JSON.stringify(result, null, 2) + '\n', 'utf8');

console.log(`Updated full descriptions (FR + EN) for ${updated} animal(s).`);
if (missing.length) {
  console.log(`Ids in map but not found in seeds (${missing.length}): ${missing.join(', ')}`);
}
